//! End-to-end Oracle test: compare our EmbeddingGemma-2 text forward against
//! HuggingFace `transformers` reference outputs.
//!
//! Reference data generated by:
//!   .venv/bin/python3 tests/oracle/run_embeddinggemma2_text_oracle.py \
//!     --input "..." --output tests/oracle/embeddinggemma2_*.json
//!
//! Run with:
//!   RMI_EMBEDDINGGEMMA_2=models/embeddinggemma-2-GGUF/embeddinggemma-2-F16.gguf \
//!   cargo test --test embeddinggemma_2_text_oracle

use std::sync::Arc;

use rust_model_inference::core::tokenizer::{BPETokenizer, EncodeOptions};

fn load_oracle(name: &str) -> (Vec<u32>, Vec<f32>, String) {
    let path = format!("tests/oracle/embeddinggemma2_{name}.json");
    let data =
        std::fs::read_to_string(&path).unwrap_or_else(|_| panic!("missing oracle file: {path}"));
    let v: serde_json::Value = serde_json::from_str(&data).expect("parse oracle JSON");
    let text = v["text"].as_str().unwrap().to_string();
    let token_ids: Vec<u32> = v["token_ids"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as u32)
        .collect();
    let embedding: Vec<f32> = v["embedding"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap() as f32)
        .collect();
    (token_ids, embedding, text)
}

#[test]
fn text_forward_matches_huggingface_oracle() {
    let Some(path) = std::env::var_os("RMI_EMBEDDINGGEMMA_2") else {
        return;
    };
    let loader = rust_model_inference::GGUFLoader::from_file(path).expect("load GGUF");
    let source: Arc<dyn rust_model_inference::TensorSource> = Arc::new(loader);
    let tokenizer = BPETokenizer::from_gguf_metadata(|key| source.metadata(key).cloned())
        .expect("EmbeddingGemma tokenizer");

    let model =
        rust_model_inference::models::embeddinggemma2::EmbeddingGemmaTextModel::from_source(
            source.as_ref(),
        )
        .expect("EmbeddingGemmaTextModel::from_source");

    let cases = ["hello", "fox", "embed", "long", "sliding"];
    let mut direct_hello = None;
    for name in &cases {
        let (token_ids, expected, text) = load_oracle(name);
        let encoded = tokenizer.encode(
            &text,
            EncodeOptions {
                add_special: true,
                parse_special: true,
            },
        );
        assert_eq!(encoded, token_ids, "{name}: tokenizer mismatch");
        let actual = model.forward(&token_ids).expect("text forward");
        if *name == "hello" {
            direct_hello = Some(actual.clone());
        }
        assert_eq!(
            actual.len(),
            expected.len(),
            "{name}: embedding dim mismatch ({} vs {})",
            actual.len(),
            expected.len()
        );
        // Compute L2 distance and cosine similarity.
        let mut dot = 0.0f64;
        let mut a_norm_sq = 0.0f64;
        let mut b_norm_sq = 0.0f64;
        let mut diff_sq = 0.0f64;
        for (a, b) in actual.iter().zip(expected.iter()) {
            let a_f = *a as f64;
            let b_f = *b as f64;
            dot += a_f * b_f;
            a_norm_sq += a_f * a_f;
            b_norm_sq += b_f * b_f;
            diff_sq += (a_f - b_f) * (a_f - b_f);
        }
        let l2 = diff_sq.sqrt();
        let denom = (a_norm_sq * b_norm_sq).sqrt();
        let cosine_sim = if denom > 0.0 { dot / denom } else { 0.0 };
        eprintln!(
            "Oracle [{name}] \"{text}\": L2={l2:.4}, cos_sim={cosine_sim:.6}, dim={}",
            actual.len()
        );
        eprintln!("  expected[:5] = {:?}", &expected[..5]);
        eprintln!("  actual  [:5] = {:?}", &actual[..5]);
        eprintln!("  expected norm = {}", b_norm_sq.sqrt());
        eprintln!("  actual norm   = {}", a_norm_sq.sqrt());
        // Text matrices are Q8_0; test direction and magnitude against the HF
        // reference instead of demanding bitwise parity after quantization.
        assert!(
            cosine_sim > 0.999 && l2 / b_norm_sq.sqrt() < 0.03,
            "{name}: cosine {cosine_sim:.6}, relative L2 {} (text=\"{text}\")",
            l2 / b_norm_sq.sqrt()
        );
    }

    let routed = rust_model_inference::app::compute_embedding(
        source.as_ref(),
        "Hello world this is a test",
        4,
    )
    .expect("app embedding dispatch");
    let direct = direct_hello.expect("hello direct result");
    let dot: f64 = routed
        .iter()
        .zip(&direct)
        .map(|(a, b)| f64::from(*a) * f64::from(*b))
        .sum();
    let routed_norm = routed
        .iter()
        .map(|value| f64::from(*value).powi(2))
        .sum::<f64>()
        .sqrt();
    let direct_norm = direct
        .iter()
        .map(|value| f64::from(*value).powi(2))
        .sum::<f64>()
        .sqrt();
    assert!(
        dot / (routed_norm * direct_norm) > 0.99999,
        "app dispatch changed EmbeddingGemma tokenization"
    );
}
